      storageSet: (k, v) => { try { self.prefs.setString('vb_' + k, v == null ? '' : String(v)); } catch (e) { } },
      config: k => { try { const v = self.prefs.get(k); return v == null || v === '' ? null : String(v); } catch (e) { return null; } },
